INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 18, 'theory', 'Квиз: менеджер и база данных');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 18, 0, 'Для чего нужен файл ответов engine-setup?', '["Для хранения паролей пользователей портала", "Для резервной копии виртуальных машин", "Чтобы повторить установку без вопросов с теми же ответами", "Чтобы менять версию совместимости кластера"]', 2, 'Файл ответов сохраняет ответы на вопросы установки; его передают в engine-setup, и установка идёт без вопросов. Так получают одинаковые менеджеры.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 18, 1, 'Что делает компенсация при сбое команды менеджера?', '["Откатывает изменения в базе по сохранённым снимкам", "Перезапускает хост, на котором случился сбой", "Удаляет связанные события из audit_log", "Повторяет команду, пока она не завершится"]', 0, 'Компенсация возвращает базу к состоянию до команды по сохранённым снимкам. События остаются: по ним видно, что произошло.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 18, 2, 'Пользователю выдана роль ClusterAdmin на кластер. Что ему доступно?', '["Только сам кластер как запись в базе", "Весь центр данных", "Только машины, созданные им самим", "Кластер и вложенные в него хосты и машины"]', 3, 'Разрешение действует на объект и на всё вложенное в него. Вверх, на центр данных, и в стороны, на соседние кластеры, оно не распространяется.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 18, 3, 'Что НЕ попадает в архив engine-backup?', '["Дамп базы engine", "Диски виртуальных машин на хранилищах", "Файлы настроек менеджера", "Файлы удостоверяющего центра"]', 1, 'Архив хранит состояние самого менеджера: базу, настройки, PKI. Диски машин лежат на хранилищах и копируются отдельно.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 18, 4, 'Когда вступает в силу значение, записанное командой engine-config?', '["Сразу, без перезапуска", "После перезапуска хостов", "После перезапуска службы ovirt-engine", "После повторной установки виртуальных машин"]', 2, 'Глобальные ключи читаются при старте менеджера, поэтому после записи его перезапускают. Настройки кластера из портала действуют сразу.');
